// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 feeRate, address _nft, address _baseToken, uint128 vBase, uint128 vNft, uint56 changeFee, bytes32 merkleRoot, bool useStolen, bool payRoyalties) public {
        if (_nft == address(0)) _nft = address(1);
        if (_baseToken == address(0)) _baseToken = address(2);

        bool ok;

        try c.initialize(_baseToken, _nft, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (feeRate <= 5000) {
            assertTrue(ok && c.initialized());
        } else {
            assertTrue(ok == c.initialized());
        }
    }
}
